{"action":"write_file","path":"bucket.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { TokenBucket } = require('./bucket');

test('a full bucket allows a burst, then refuses', () => {
  const b = new TokenBucket(3, 1);
  assert.equal(b.tryTake(0), true);
  assert.equal(b.tryTake(0), true);
  assert.equal(b.tryTake(0), true);
  assert.equal(b.tryTake(0), false);
});

test('tokens come back over time', () => {
  const b = new TokenBucket(1, 1);
  assert.equal(b.tryTake(0), true);
  assert.equal(b.tryTake(500), false);
  assert.equal(b.tryTake(1000), true);
});

test('constructor validation', () => {
  assert.throws(() => new TokenBucket(0, 1), RangeError);
  assert.throws(() => new TokenBucket(-1, 1), RangeError);
  assert.throws(() => new TokenBucket(NaN, 1), RangeError);
  assert.throws(() => new TokenBucket(Infinity, 1), RangeError);
  assert.throws(() => new TokenBucket(1, 0), RangeError);
  assert.throws(() => new TokenBucket(1, -1), RangeError);
  assert.throws(() => new TokenBucket(1, NaN), RangeError);
  assert.throws(() => new TokenBucket(1, Infinity), RangeError);
});

test('tryTake validation of n and nowMs', () => {
  const b = new TokenBucket(5, 1);
  assert.throws(() => b.tryTake(0, 0), RangeError);
  assert.throws(() => b.tryTake(0, -1), RangeError);
  assert.throws(() => b.tryTake(0, 1.5), RangeError);
  assert.throws(() => b.tryTake(0, NaN), RangeError);
  assert.throws(() => b.tryTake('0', 1), TypeError);
  assert.throws(() => b.tryTake(NaN, 1), TypeError);
  assert.throws(() => b.tryTake(Infinity, 1), TypeError);
});

test('available validation of nowMs', () => {
  const b = new TokenBucket(5, 1);
  assert.throws(() => b.available('0'), TypeError);
  assert.throws(() => b.available(NaN), TypeError);
  assert.throws(() => b.available(Infinity), TypeError);
});

test('clock running backwards does not refill or change lastTime', () => {
  const b = new TokenBucket(1, 1);
  assert.equal(b.tryTake(1000), true);
  assert.equal(b.available(1000), 0);
  // Time goes backwards
  assert.equal(b.available(500), 0);
  // Moving forward from 1000 by 500ms should add 0.5 tokens
  assert.equal(b.available(1500), 0.5);
});
